    const remarkPlugins: MDXPlugin[] = [
      ...(reqOptions.beforeDefaultRemarkPlugins ?? []),
      directives,
      ...getAdmonitionsPlugins(reqOptions.admonitions ?? false),
      ...DEFAULT_OPTIONS.remarkPlugins,
      details,
      head,
      ...(reqOptions.markdownConfig.mermaid ? [mermaid] : []),
